import{_ as e,a as t,b as o,c as r,d as n,e as s,f as i}from"./chunks/ee-ohos-12.CpDpCxcb.js";import{_ as b,o as d,c as l,a3 as p}from"./chunks/framework.BveOjhN0.js";const k=JSON.parse('{"title":"App on HarmonyOS","description":"","frontmatter":{"title":"App on HarmonyOS"},"headers":[],"relativePath":"050.openharmony/02.hap.md","filePath":"050.openharmony/02.hap.md","lastUpdated":1782655224000}'),c={name:"050.openharmony/02.hap.md"};function m(g,a,u,v,h,y){return d(),l("div",null,[...a[0]||(a[0]=[p('<div class="hero" data-v-b92b320a><div class="hero-badges" data-v-b92b320a><span class="badge badge--star" data-v-b92b320a>⭐ 8000+ Star</span><span class="badge badge--version" data-v-b92b320a>🚀 v5</span><span class="badge badge--ohos" data-v-b92b320a>🪶 HarmonyOS</span></div><h1 class="hero-title" data-v-b92b320a>ElectronEgg: v5 Upgrade — Easily Build HarmonyOS Apps</h1><div class="hero-actions" data-v-b92b320a><a class="btn btn--primary" href="https://github.com/dromara/electron-egg" target="_blank" rel="noopener" data-v-b92b320a>GitHub Repo →</a><a class="btn btn--ghost" href="#wrapping-up" data-v-b92b320a>Join Community</a></div></div><blockquote data-v-b92b320a><p data-v-b92b320a>One codebase, packaged for Windows, Mac, and Linux — and now it runs directly on HarmonyOS. ElectronEgg v5 brings HarmonyOS support.</p></blockquote><h2 id="introduction" tabindex="-1" data-v-b92b320a>Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;" data-v-b92b320a>​</a></h2><p data-v-b92b320a>Since it was open-sourced, <a href="https://github.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-b92b320a>ElectronEgg</a>&#39;s vision has stayed simple: <strong data-v-b92b320a>empower every developer to master desktop software development</strong>. It brings front-end and back-end engineering practices into desktop development, wrapping Electron&#39;s complexity behind a clean controller / service / preload layered architecture. The framework has now amassed <strong data-v-b92b320a>8000+ Stars</strong> across the web, validated by long-term use across many teams — you can use it with confidence.</p><p data-v-b92b320a>Building on this, v5 delivers a major upgrade — and one of its headline capabilities is: <strong data-v-b92b320a>effortlessly build HarmonyOS apps</strong>.</p><p data-v-b92b320a>After repeated attempts, we finally got ElectronEgg running on HarmonyOS devices. It&#39;s still in the <strong data-v-b92b320a>testing phase</strong>, but the entire workflow already works end to end — see the screenshots below.</p><h2 id="harmonyos-support-one-codebase-running-on-harmonyos" tabindex="-1" data-v-b92b320a>HarmonyOS Support: One Codebase, Running on HarmonyOS <a class="header-anchor" href="#harmonyos-support-one-codebase-running-on-harmonyos" aria-label="Permalink to &quot;HarmonyOS Support: One Codebase, Running on HarmonyOS&quot;" data-v-b92b320a>​</a></h2><p data-v-b92b320a>In the past, porting an Electron app to HarmonyOS essentially meant &quot;rewriting it from scratch&quot;. v5 automatically extracts your build artifacts into the HarmonyOS HAP, where they are loaded by the HAP project&#39;s web engine. <strong data-v-b92b320a>Your existing ElectronEgg business code runs as a HarmonyOS app with almost no changes.</strong></p><p data-v-b92b320a>Below are real screenshots of the ElectronEgg demo app running on HarmonyOS:</p><blockquote data-v-b92b320a><p data-v-b92b320a>App installed on the HarmonyOS system</p></blockquote><div class="center-logo" data-v-b92b320a><img src="'+e+'" alt="logo" data-v-b92b320a></div><p data-v-b92b320a><img src="'+t+'" alt="ElectronEgg demo in the HarmonyOS AppCenter" data-v-b92b320a></p><blockquote data-v-b92b320a><p data-v-b92b320a>App launching</p></blockquote><p data-v-b92b320a><img src="'+o+'" alt="ElectronEgg demo launching" data-v-b92b320a></p><blockquote data-v-b92b320a><p data-v-b92b320a>Framework feature demo: communication, controllers, services and other capabilities work normally on HarmonyOS</p></blockquote><p data-v-b92b320a><img src="'+r+'" alt="ElectronEgg demo feature showcase" data-v-b92b320a></p><blockquote data-v-b92b320a><p data-v-b92b320a>Local image loading demo</p></blockquote><p data-v-b92b320a><img src="'+n+'" alt="ElectronEgg demo feature showcase" data-v-b92b320a></p><blockquote data-v-b92b320a><p data-v-b92b320a>Dock bar demo</p></blockquote><p data-v-b92b320a><img src="'+s+'" alt="ElectronEgg demo feature showcase" data-v-b92b320a></p><blockquote data-v-b92b320a><p data-v-b92b320a>Web page loading demo</p></blockquote><p data-v-b92b320a><img src="'+i+'" alt="ElectronEgg demo feature showcase" data-v-b92b320a></p><p data-v-b92b320a>As you can see, a desktop app originally built for Windows / Mac runs smoothly on HarmonyOS — from installation to every feature. That&#39;s the core message of v5&#39;s HarmonyOS support: <strong data-v-b92b320a>cross-platform is no longer a slogan; HarmonyOS is a first-class citizen.</strong></p><h2 id="what-else-is-new-in-v5" tabindex="-1" data-v-b92b320a>What Else Is New in v5 <a class="header-anchor" href="#what-else-is-new-in-v5" aria-label="Permalink to &quot;What Else Is New in v5&quot;" data-v-b92b320a>​</a></h2><p data-v-b92b320a>Beyond HarmonyOS support, v5 also gives the framework core a fairly thorough refactor:</p><ul data-v-b92b320a><li data-v-b92b320a>Full TypeScript refactor: every API now has complete type definitions.</li><li data-v-b92b320a>Dual module output: supports both CJS and ESM formats.</li><li data-v-b92b320a>Pino logging: a more powerful logging system.</li><li data-v-b92b320a>Bundle registry: faster startup.</li><li data-v-b92b320a>Main-process bundling: main-process code can be bundled just like front-end code.</li><li data-v-b92b320a>Build config overhaul: many fine-grained control options added.</li><li data-v-b92b320a>Encryption upgrade: more secure.</li><li data-v-b92b320a>ee-bin overhaul: now ships a complete TypeScript type system.</li></ul><h2 id="who-is-it-for" tabindex="-1" data-v-b92b320a>Who Is It For <a class="header-anchor" href="#who-is-it-for" aria-label="Permalink to &quot;Who Is It For&quot;" data-v-b92b320a>​</a></h2><ul data-v-b92b320a><li data-v-b92b320a>Developers who want to build desktop software with a front-end stack (Vue / React / HTML)</li><li data-v-b92b320a>Teams that need to ship internal tools, admin consoles, or office software as desktop apps</li><li data-v-b92b320a>Products that must cover Windows, Mac, Linux, <strong data-v-b92b320a>and HarmonyOS</strong></li><li data-v-b92b320a>Teams looking to lower Electron&#39;s learning curve and want a clear architecture</li></ul><p data-v-b92b320a>Whether you&#39;re a front-end, back-end, ops, or client developer, you can get started quickly.</p><h2 id="wrapping-up" tabindex="-1" data-v-b92b320a>Wrapping Up <a class="header-anchor" href="#wrapping-up" aria-label="Permalink to &quot;Wrapping Up&quot;" data-v-b92b320a>​</a></h2><p data-v-b92b320a>Desktop software — office tools, personal utilities — will remain a real, lasting need on the PC for the next decade. ElectronEgg exists to make building it simple, and now that simplicity extends to HarmonyOS.</p><p data-v-b92b320a>The framework is already widely used in clients for accounting, government, enterprise, healthcare, education, stock trading, ERP, entertainment, video and more — feel free to use it with confidence.</p><div class="tip custom-block" data-v-b92b320a><p class="custom-block-title" data-v-b92b320a>Open Source &amp; Community</p><ul data-v-b92b320a><li data-v-b92b320a>GitHub: <a href="https://github.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-b92b320a>https://github.com/dromara/electron-egg</a></li><li data-v-b92b320a>Gitee: <a href="https://gitee.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-b92b320a>https://gitee.com/dromara/electron-egg</a></li></ul></div><p data-v-b92b320a>If it helps you, a Star is appreciated — and come join the community to chat.</p>',34)])])}const _=b(c,[["render",m],["__scopeId","data-v-b92b320a"]]);export{k as __pageData,_ as default};
